<script lang="ts">
 import { planBlend } from '@vinea/domain';
 import { forms,label } from '$lib/forms';import { translator } from '$lib/app-i18n';import type { Language } from '$lib/i18n';import { invalidateAll } from '$app/navigation';import { saveDraft } from '$lib/offline';
 let {type,model,lang,tenantId}:{type:string;model:Record<string,Record<string,any>[]>;lang:Language;tenantId:string}=$props();
 let t=$derived(translator(lang));let fields=$derived(forms[type]);let volumes=$state<Record<string,string>>({});
 let preview=$derived.by(()=>{if(!['recipe_save','mix'].includes(type))return null;try{return planBlend(model.positions.map(p=>{const lot=model.lots.find(l=>l.id===p.lot_id);const superseded=new Set(model.analyses.map(a=>a.supersedes).filter(Boolean));const analysis=model.analyses.find(a=>a.lot_id===p.lot_id&&a.parameter==='alcohol'&&a.quality==='measured'&&!superseded.has(a.id));return {id:p.id,volume:volumes[p.id]||'0',available:p.available_l,cost:lot?.cost_per_l??'0',alcohol:analysis?.value??null,unit:analysis?.unit??null,method:analysis?.method??null,blocked:p.blocked};}));}catch{return null;}});let message=$state(''),busy=$state(false),retryKey=$state('');
 async function submit(event:SubmitEvent){event.preventDefault();if(busy)return;const form=event.currentTarget as HTMLFormElement;const data=new FormData(form);const command:Record<string,any>={type};
  for(const field of fields){if(field.type==='sources'||field.type==='components'){command[field.key]=model.positions.filter(p=>Number(data.get('source_'+p.id))>0).map(p=>({position_id:p.id,quantity_l:String(data.get('source_'+p.id)),...(field.type==='sources'?{expected_version:p.version}:{})}));continue;}
   if(field.type==='checklist'){command.checklist=String(data.get(field.key)??'').split('\n').map(s=>s.trim()).filter(Boolean).map(label=>({label,done:false}));continue;}
   if(field.type==='multiselect'){command[field.key]=data.getAll(field.key);continue;}
   if(field.type==='checkbox'){command[field.key]=data.has(field.key);continue;}
   const value=data.get(field.key)?.toString()??'';if(!value&&field.optional)continue;command[field.key]=field.type==='number'?Number(value):field.type==='datetime'?new Date(value).toISOString():value;
  }
  for(const [key,collection] of [['vessel_id','vessels'],['position_id','positions'],['lot_id','lots'],['recipe_id','recipes'],['task_id','tasks'],['order_id','orders']]){if(command[key]&&['vessel_update','transfer','split','loss','adjustment','bottle','reserve','lot_block','recipe_freeze','approve','task_update','approve_deviation','produce'].includes(type)){const row=model[collection].find(r=>r.id===command[key]);if(row)command[type==='produce'&&key==='order_id'?'order_version':'expected_version']=row.version;}}
  if(type==='produce')delete command.expected_version;
  busy=true;message='';const key=retryKey||crypto.randomUUID();
  try{if(!navigator.onLine){await saveDraft(tenantId,command,key);message=t('draftSaved');return;}
   const res=await fetch('/api/commands',{method:'POST',headers:{'content-type':'application/json','idempotency-key':key},body:JSON.stringify(command)});
   const result=await res.json();if(!res.ok){retryKey='';message=result.message==='MFA_REQUIRED'?t('mfaRequired'):result.message==='VERSION_CONFLICT'?t('conflict'):result.message?t(result.message):t('INVALID_INPUT');return;}
   retryKey='';message=t('saved');form.reset();volumes={};await invalidateAll();
  }catch(cause){retryKey=key;message=cause instanceof Error?cause.message:'Connection failed';}finally{busy=false;}
 }
</script>
<details class="command"><summary>{t(type)}</summary><form onsubmit={submit}><div class="fields">{#each fields as field}<label class:wide={field.type==='textarea'||field.type==='components'||field.type==='sources'}><span>{t(field.key)}</span>{#if field.type==='select'}<select name={field.key} required={!field.optional}><option value="">—</option>{#if field.options}{#each field.options as option}<option value={option}>{t(option)}</option>{/each}{:else}{#each model[field.collection??'']??[] as row}<option value={field.key==='correction_of'?row.operation_id:row.id}>{label(row,field.collection??'')}</option>{/each}{/if}</select>{:else if field.type==='multiselect'}<select name={field.key} multiple size="4">{#each model[field.collection??'']??[] as row}<option value={row.id}>{label(row,field.collection??'')}</option>{/each}</select>{:else if field.type==='sources'||field.type==='components'}<div class="sources">{#each model.positions.filter(p=>Number(p.quantity_l)>0) as p}<label><span>{label(p,'positions')}</span><input name={'source_'+p.id} oninput={(e)=>volumes[p.id]=e.currentTarget.value} inputmode="decimal" type="number" min="0" step="0.001" placeholder="0" /></label>{/each}</div>{:else if field.type==='checklist'}<textarea name={field.key} rows="3" maxlength="5000" placeholder={t('onePerLine')}></textarea>{:else if field.type==='textarea'}<textarea name={field.key} required={!field.optional} maxlength="5000" rows="3"></textarea>{:else if field.type==='checkbox'}<input type="checkbox" name={field.key} />{:else}<input name={field.key} type={field.type==='datetime'?'datetime-local':field.type==='number'?'number':'text'} value={field.type==='datetime'?new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):field.value??''} min={field.min} max={field.max} required={!field.optional} maxlength="2000" />{/if}</label>{/each}</div>{#if preview}<div class="preview"><strong>{preview.volume} L · {preview.costPerLiter} €/L</strong><p>{t('alcohol')} · {preview.alcohol??t('missing')} {preview.alcohol?'% vol':''}</p><p>{t('ph')}</p></div>{/if}<button disabled={busy}>{busy?t('saving'):t(type)}</button>{#if message}<p role="status" class="message">{message}</p>{/if}</form></details>
<style>.command{border:1px solid #dfe5da;border-radius:9px;background:white;margin:10px 0}.command summary{padding:16px 18px;cursor:pointer;font-weight:500;font-size:13px}.command[open] summary{border-bottom:1px solid #eef0e9}form{padding:18px}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px;margin-bottom:20px}.wide{grid-column:1/-1}.sources{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;background:#f8faf5;border-radius:7px;padding:12px}.sources label{font-size:10px}input[type=checkbox]{width:18px;height:18px}.message{font-size:12px;overflow-wrap:anywhere}</style>
